mapper.select:
SELECT PRD_DESIGN_ID id, PRD_DESIGN_SERIAL_NAME text, REQUIREMENT_ID OBJECT FROM PRODUCT_DESIGN_INFO
DATA_STATUS = #{DATA_STATUS}
AND (PRD_DESIGN_ID like CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) or PRD_DESIGN_SERIAL_NAME like CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')))
AND PRD_DESIGN_ID = #{initValue}

select DATA_STATUS as dataStatus, MOCK_DATE as mockDate, GENERATE_TIME as generateTime, PRD_DESIGN_ID as prdDesignId, PRD_SCALE as prdScale, PRD_PERIOD as prdPeriod, RATE_MAX as rateMax, RATE_MIX as rateMix, SEQ_NO seqNo, REQUIREMENT_ID requirementId, null as workflowId FROM MOCK_RESULT_INFO M where 1=1
AND (M.PRD_DESIGN_ID in
null) or M.PRD_DESIGN_ID in (
#{item}
)
and M.MOCK_DATE = to_date(#{mockDate}, 'yyyy-MM-dd')
and M.DATA_STATUS = #{dataStatus}
UNION All select WORKFLOW_STATUS as dataStatus, MOCK_DATE as mockDate, GENERATE_TIME as generateTime, PRD_DESIGN_ID as prdDesignId, PRD_SCALE as prdScale, PRD_PERIOD as prdPeriod, RATE_MAX as rateMax, RATE_MIX as rateMix, SEQ_NO seqNo, REQUIREMENT_ID requirementId, WORKFLOW_ID as workflowId FROM WFL_MOCK_RESULT_INFO WMRI where 1=1
AND (WMRI.PRD_DESIGN_ID in
null) or WMRI.PRD_DESIGN_ID in (
#{item}
)
and WMRI.MOCK_DATE = to_date(#{mockDate}, 'yyyy-MM-dd')
and WMRI.WORKFLOW_STATUS = #{dataStatus}

mapper.delete:
		delete from MOCK_TRADE_DEAL
 			where PRD_DESIGN_ID = #{prdDesignId}
   		AND BATCH_ID = #{batchId}

mapper.select:
select item_code id,
	   item_value text,
	   case when dict_code = #{SECRATE_DATA}
	      then #{BENCHMARK_TYPE_04}
	    when dict_code = #{CURVE_CODE}
	      then #{BENCHMARK_TYPE_03}
	       else #{BENCHMARK_TYPE_02}
	     end object,
	    case when dict_code = #{SECRATE_DATA}
	       then #{BENCHMARK_TYPE_NAME_04}
	     when dict_code = #{CURVE_CODE}
	       then #{BENCHMARK_TYPE_NAME_03}
	       else #{BENCHMARK_TYPE_NAME_02}
	     end  col   
	from sys_datadict_list

	 dict_code in (#{SECRATE_DATA},#{CURVE_CODE},#{MARKET_ID})

	AND (item_code like CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%'))
		or
		item_value like CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')))


	 AND item_code = #{initValue}


order by dict_code,order_no
